<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import PageHeading from '@/components/PageHeading.vue'
import RecordEditor from '@/components/RecordEditor.vue'
import DeleteRecord from '@/components/DeleteRecord.vue'
import { workspace } from '@/lib/workspace'
import { dateLabel } from '@/lib/domain'
import type { Entity, Kind } from '@/lib/types'
const route = useRoute(), isClient = computed(() => route.path === '/clients'), kind = computed<Kind>(() => isClient.value ? 'client' : 'project')
const filter = ref('all'), editor = ref<{kind: Kind; record?: Entity} | null>(null), deleting = ref<{kind:Kind;record:Entity;label:string}|null>(null)
const projects = computed(() => workspace.data!.projects.filter(p => filter.value === 'all' || p.status === filter.value))
</script>
<template><PageHeading :title="isClient ? 'Clients' : 'Projects'" :subtitle="isClient ? 'The people and businesses behind your projects.' : 'Client work, from the first brief to the final follow-up.'"><button class="primary" :disabled="!isClient && !workspace.data?.clients.length" @click="editor={kind}">Add {{ isClient ? 'client' : 'project' }}</button></PageHeading><template v-if="isClient"><div v-if="!workspace.data?.clients.length" class="empty"><h2>Your next good project starts here.</h2><p>Add a client to create their first project.</p><button class="primary" @click="editor={kind:'client'}">Add client</button></div><div v-else class="record-list"><article v-for="c in workspace.data?.clients" :key="c.id" class="client-row"><div><h2>{{ c.name }}</h2><small>{{ workspace.data!.projects.filter(p => p.client_id === c.id).length }} projects</small></div><div class="actions"><button class="small" @click="editor={kind:'client',record:c}">Edit client</button><button class="small danger" @click="deleting={kind:'client',record:c,label:c.name}">Delete client</button></div></article></div></template><template v-else><div v-if="!workspace.data?.clients.length" class="notice">Create a client before adding their first project. <RouterLink to="/clients">Go to clients</RouterLink></div><div class="filters" aria-label="Project state"><button v-for="state in ['all','active','completed','archived']" :key="state" :class="{selected:filter === state}" :aria-pressed="filter === state" @click="filter=state">{{ state[0]!.toUpperCase() + state.slice(1) }}</button></div><article v-for="p in projects" :key="p.id" class="project-row"><div><RouterLink class="title" :to="'/projects/'+p.id">{{ p.name }}</RouterLink><small>{{ workspace.data?.clients.find(c => c.id === p.client_id)?.name }}</small></div><div class="secondary">{{ workspace.data!.tasks.filter(t => t.project_id === p.id && !t.completed).length }} open tasks</div><div><span class="pill" :class="p.status">{{ p.status }}</span></div><div class="row-date">{{ p.deadline ? 'Due '+dateLabel(p.deadline) : 'No deadline' }}</div><div class="actions"><button class="small quiet" @click="editor={kind:'project',record:p}">Edit</button><button class="small danger" @click="deleting={kind:'project',record:p,label:p.name}">Delete</button></div></article><div v-if="!projects.length" class="empty"><h2>No {{ filter === 'all' ? '' : filter }} projects yet.</h2><p>{{ workspace.data?.clients.length ? 'Add a project to organize tasks, deadlines and unpaid invoices.' : 'Create a client first, then add their project.' }}</p></div></template><RecordEditor v-if="editor" :kind="editor.kind" :record="editor.record" @close="editor=null" /><DeleteRecord v-if="deleting" v-bind="deleting" @close="deleting=null" /></template>
